UPDATE site_presentation SET content_json = jsonb_set(content_json, '{pages,home,introBody}',
    jsonb_build_object(
        'vi', $$Đàng Xem là xưởng gốm gia đình trong làng gốm Chăm Bàu Trúc, Khánh Hòa (trước thuộc Ninh Thuận), ngôi làng được xem là cổ nhất Đông Nam Á. Ngày 29/11/2022, nghệ thuật làm gốm của người Chăm được UNESCO ghi danh vào Danh sách di sản văn hóa phi vật thể cần bảo vệ khẩn cấp. Ở xưởng, gốm vẫn được làm theo cách cũ: nghệ nhân đi vòng quanh khối đất để nặn, không dùng bàn xoay, rồi nung lộ thiên bằng củi và rơm. Mỗi món ra lò mang màu đất và vân khói riêng, không chiếc nào giống chiếc nào. Bạn có thể mang một phần di sản ấy về nhà qua bộ sưu tập bình, tượng, phù điêu và tiểu cảnh gốm giao toàn quốc, hoặc ghé tận xưởng, ngồi cạnh nghệ nhân và tự tay nặn món gốm của riêng mình.$$,
        'en', $$Đàng Xem is a family pottery workshop in the Cham village of Bàu Trúc, Khánh Hòa (formerly Ninh Thuận), one of Southeast Asia’s oldest active pottery villages. On 29 November 2022, Cham pottery making was inscribed on UNESCO’s List of Intangible Cultural Heritage in Need of Urgent Safeguarding. Artisans still shape clay by walking around it without a wheel, then fire pieces outdoors with wood and straw. Each piece carries its own earth tones and smoke patterns. Explore our pottery collection or visit the workshop to make a piece yourself.$$)), updated_at=now()
WHERE id=1 AND content_json #> '{pages,home,introBody}' IS NULL;
